#!/usr/bin/env bash
set -euo pipefail
expected_account="$1"
mode="${2:-}"
[[ "$mode" == '' || "$mode" == '--defer-spotify' ]]
test "$(aws sts get-caller-identity --query Account --output text --region ca-central-1)" = "$expected_account"
# This file is generated by the masked helper with shell-safe credential values.
source /home/ubuntu/sentimentscribe/deploy/ec2/.env.prod
if [ "$mode" = '--defer-spotify' ]; then
  test -z "$SPOTIFY_CLIENT_ID"
  test -z "$SPOTIFY_CLIENT_SECRET"
  sudo docker exec sentimentscribe-backend sh -c 'test -z "$SPOTIFY_CLIENT_ID" && test -z "$SPOTIFY_CLIENT_SECRET"'
  tmdb_status=$(curl -sS -o /dev/null -w '%{http_code}' --get --data-urlencode "api_key=$TMDB_API_KEY" https://api.themoviedb.org/3/configuration)
  unset SPOTIFY_CLIENT_ID SPOTIFY_CLIENT_SECRET TMDB_API_KEY POSTGRES_PASSWORD SENTIMENTSCRIBE_JWT_SECRET
  printf 'Spotify: intentionally deferred; both fields verified blank. TMDb HTTP status: %s\n' "$tmdb_status"
  test "$tmdb_status" = '200'
  exit 0
fi
spotify_response=$(curl -sS --user "$SPOTIFY_CLIENT_ID:$SPOTIFY_CLIENT_SECRET" --data 'grant_type=client_credentials' https://accounts.spotify.com/api/token)
spotify_token=$(printf '%s' "$spotify_response" | python3 -c 'import json,sys; print(json.load(sys.stdin).get("access_token", ""))')
spotify_status='NOT_TESTED'
if [ -n "$spotify_token" ]; then
  echo 'Spotify OAuth authentication: passed'
  spotify_search=$(curl -sS -w '\n%{http_code}' -H "Authorization: Bearer $spotify_token" --get --data-urlencode 'q=happy' --data-urlencode 'type=track' --data-urlencode 'limit=5' https://api.spotify.com/v1/search)
  spotify_status=${spotify_search##*$'\n'}
  if [ "$spotify_status" != 200 ]; then
    printf '%s' "${spotify_search%$'\n'*}" | python3 -c 'import json,sys
try:
    data=json.load(sys.stdin); message=str(data.get("error",{}).get("message","")).lower()
except (ValueError,AttributeError):
    message=""
category="premium_requirement" if "premium" in message else "user_allowlist" if "registered" in message else "app_access_policy" if "app" in message or "permission" in message else "no_specific_reason"
print("Spotify search error category: " + category)'
    spotify_market_status=$(curl -sS -o /dev/null -w '%{http_code}' -H "Authorization: Bearer $spotify_token" --get --data-urlencode 'q=happy' --data-urlencode 'type=track' --data-urlencode 'limit=5' --data-urlencode 'market=CA' https://api.spotify.com/v1/search)
    printf 'Spotify search with explicit CA market HTTP status: %s\n' "$spotify_market_status"
  fi
else
  printf '%s' "$spotify_response" | python3 -c 'import json,sys; code=json.load(sys.stdin).get("error"); allowed={"invalid_client","invalid_request","unauthorized_client","unsupported_grant_type","access_denied"}; print("Spotify OAuth result: " + (code if code in allowed else "authentication failed"))'
fi
tmdb_status=$(curl -sS -o /dev/null -w '%{http_code}' --get --data-urlencode "api_key=$TMDB_API_KEY" https://api.themoviedb.org/3/configuration)
unset spotify_token spotify_response spotify_search SPOTIFY_CLIENT_ID SPOTIFY_CLIENT_SECRET TMDB_API_KEY POSTGRES_PASSWORD SENTIMENTSCRIBE_JWT_SECRET
printf 'Spotify client-credentials/search HTTP status: %s\nTMDb API-key authentication HTTP status: %s\n' "$spotify_status" "$tmdb_status"
test "$spotify_status" = '200'
test "$tmdb_status" = '200'
echo 'Provider authentication checks passed without printing tokens or keys.'
